var d = msg.payload;
if (!d || typeof d.co2_ppm === 'undefined') {
    node.warn('Keine Sensordaten von /api/latest');
    return [null, null];
}
var co2 = d.co2_ppm;
var warn = d.co2_warning;
var crit = d.co2_critical;

var color = 'green';
if (co2 >= crit) { color = 'red'; }
else if (co2 >= warn) { color = 'yellow'; }

node.status({ fill: color === 'yellow' ? 'yellow' : (color === 'red' ? 'red' : 'green'), shape: 'dot', text: co2 + ' ppm' });

// Ausgang 1: LED-Farbe als Argument fuer den exec-Node
var ledMsg = { payload: color };

// Ausgang 2: E-Mail nur bei kritischem Wert (rot)
var alertMsg = null;
if (color === 'red') {
    alertMsg = {
        topic: 'SmartRoom Alarm: CO2 kritisch (' + co2 + ' ppm)',
        payload: 'Achtung! Die CO2-Konzentration liegt bei ' + co2 + ' ppm (Grenzwert ' + crit + ' ppm).\n' +
                 'Temperatur: ' + d.temperature + ' C, Luftfeuchtigkeit: ' + d.humidity + ' %.\n\n' +
                 'Bitte den Raum lueften.'
    };
}

return [ledMsg, alertMsg];
